# 温度监控与告警脚本
import subprocess
import json
from datetime import datetime

class ThermalMonitor:
    def __init__(self):
        self.thresholds = {
            'cpu': {'warning': 75, 'critical': 85},
            'memory': {'warning': 70, 'critical': 80},
            'system': {'warning': 35, 'critical': 40},
        }

    def get_temperatures(self):
        temps = {}

        # 从IPMI获取温度
        result = subprocess.run(
            ['ipmitool', 'sensor'],
            capture_output=True, text=True
        )

        for line in result.stdout.split('\n'):
            if 'Temp' in line or 'temp' in line:
                parts = line.split('|')
                if len(parts) >= 2:
                    name = parts[0].strip()
                    value = parts[1].strip()
                    try:
                        temps[name] = float(value.split()[0])
                    except:
                        pass

        return temps

    def check_thresholds(self, temps):
        alerts = []

        for name, value in temps.items():
            for category, limits in self.thresholds.items():
                if category.lower() in name.lower():
                    if value >= limits['critical']:
                        alerts.append({
                            'level': 'CRITICAL',
                            'sensor': name,
                            'value': value,
                            'threshold': limits['critical']
                        })
                    elif value >= limits['warning']:
                        alerts.append({
                            'level': 'WARNING',
                            'sensor': name,
                            'value': value,
                            'threshold': limits['warning']
                        })

        return alerts

    def get_fan_status(self):
        fans = []

        result = subprocess.run(
            ['ipmitool', 'sensor'],
            capture_output=True, text=True
        )

        for line in result.stdout.split('\n'):
            if 'Fan' in line or 'fan' in line:
                parts = line.split('|')
                if len(parts) >= 4:
                    fans.append({
                        'name': parts[0].strip(),
                        'rpm': parts[1].strip(),
                        'status': parts[3].strip()
                    })

        return fans

    def generate_report(self):
        temps = self.get_temperatures()
        fans = self.get_fan_status()
        alerts = self.check_thresholds(temps)

        report = {
            'timestamp': datetime.now().isoformat(),
            'temperatures': temps,
            'fans': fans,
            'alerts': alerts,
            'status': 'CRITICAL' if any(a['level'] == 'CRITICAL' for a in alerts)
                      else 'WARNING' if alerts else 'OK'
        }

        return report

if __name__ == '__main__':
    monitor = ThermalMonitor()
    report = monitor.generate_report()
    print(json.dumps(report, indent=2))
